#!/usr/bin/env python3
"""Render every generated file in the repository from a :class:`model.Catalog`.

Pure: ``build(catalog, today)`` returns ``{path: text}`` and touches nothing, so
the tests can render the whole repository from a fixture and compare bytes.

The layout is shaped by one requirement — **the first screen of the README must
tell any tech candidate, intern to Staff+, where their list is, and take them
there in one click** — and by one constraint: GitHub stops rendering a markdown
file at 512,000 bytes. So the README is an index (a role × level matrix, every
industry, the companies with the most OAs, the newest rows anywhere) and the
rows live in capped, paginated pages.

The shape follows what the most-starred lists of this kind do: one category bar
by role with a count beside each (the job lists), a legend before the first
table, newest-first rows with a freshness badge, and a one-click practice
button on every row.
"""

from __future__ import annotations

import csv
import io
import json
from collections import Counter
from datetime import date

from model import (
    FORMAT_SHORT,
    FORMATS,
    GUIDE_ROLES,
    INDUSTRIES,
    INDUSTRY_BY_ID,
    LEVEL_SHORT,
    LEVEL_TRACKS,
    MIN_LIST_ROWS,
    MONTHS,
    RECENT_DAYS,
    ROLES,
    ROUND_EMOJI,
    ROUND_LABELS,
    ROUND_SHORT,
    ROUNDS,
    SPECIALTIES,
    TRACK_BY_ID,
    Catalog,
    Question,
    in_industry,
    industries_of,
    is_future,
    is_recent,
    list_slug,
    newest_first,
    sector_industry,
    seen_text,
)

SITE = "https://trueinterview.io"
REPO = "kevin-2023-code/Tech-OA-Questions"
SISTER = "https://github.com/kevin-2023-code/Tech-Interview-Questions"
NEW_GRAD = "https://github.com/kevin-2023-code/New-Grad-Opportunities"
INTERNSHIPS = "https://github.com/kevin-2023-code/Internship-Opportunities"
SUBMIT = f"https://github.com/{REPO}/issues/new?template=oa-report.yml"

GENERATED = "<!-- Generated by scripts/sync.py from the TrueInterview catalog. Do not edit by hand: the next sync overwrites it. -->"

README_ROWS = 120
PAGE_ROWS = 400
TOP_OA_COMPANIES = 12

#: GitHub truncates a rendered markdown file at 512,000 bytes. Both budgets leave
#: a wide margin, and sync.py writes NOTHING when one is exceeded.
README_MAX_BYTES = 160_000
PAGE_MAX_BYTES = 400_000

LEGEND = "Newest first · 🔥 reported in the last 14 days · 🆕 last 45 days · **Level** = the level the loop was reported at · a dash means not recorded"

FORMAT_TITLES = {
    "algorithm": "Coding (Algorithm)",
    "system-design": "System Design",
    "object-oriented-programming": "Object-Oriented & Low-Level Design",
    "sql": "SQL",
    "ai-coding": "AI Coding",
}

#: Role names as they read inside a page title ("Software Engineer OA ...").
ROLE_TITLES = {
    "swe": "Software Engineer",
    "ml-research": "ML Engineer, AI Engineer & Research Scientist",
    "data": "Data Scientist",
    "quant-roles": "Quant Researcher, Developer & Trader",
    "pm": "Product Manager",
    "hardware": "Hardware Engineer",
    "backend": "Backend Engineer",
    "frontend": "Frontend Engineer",
    "platform": "Platform & Infrastructure Engineer",
    "manager": "Engineering Manager",
}
LEVEL_TITLES = {"new-grad": "Intern & New Grad", "mid": "Mid-Level", "senior": "Senior", "staff": "Staff+"}


# ── Cells ────────────────────────────────────────────────────────────────────


def esc(text: str) -> str:
    """Make free text safe inside a table cell and a link label."""
    return (
        text.replace("\\", "\\\\")
        .replace("|", "\\|")
        .replace("[", "\\[")
        .replace("]", "\\]")
        .replace("<", "&lt;")
        .replace("\n", " ")
    )


def num(n: int) -> str:
    return f"{n:,}"


def _count(n: int) -> str:
    return num(n) if n else "—"


def company_cell(q: Question, root: str, skip: str | None = None) -> str:
    parts = []
    for name, key in zip(q.companies, q.company_keys):
        if key == skip:
            continue
        parts.append(f"[{esc(name)}]({root}companies/{key}.md)")
    if not parts:
        return "—"
    shown = parts[:3]
    if len(parts) > 3:
        shown.append(f"+{len(parts) - 3}")
    first = f"**{shown[0]}**" if skip is None else shown[0]
    return " / ".join([first, *shown[1:]])


def level_cell(q: Question) -> str:
    return " · ".join(LEVEL_SHORT[level] for level in q.levels) or "—"


def round_cell(q: Question) -> str:
    return " · ".join(ROUND_SHORT[r] for r in q.rounds) or "—"


def format_cell(q: Question) -> str:
    return FORMAT_SHORT.get(q.format, q.format) or "—"


def practice_cell(q: Question) -> str:
    return f"[![Free][f]]({q.url})" if q.free else f"[![Practice][p]]({q.url})"


def table(questions: list[Question], today: date, root: str, company: str | None = None) -> list[str]:
    head = "| Question | Round | Level | Format | Solve | Seen |" if company else "| Company | Question | Round | Level | Format | Solve | Seen |"
    rule = "| :-- | :-- | :-- | :-- | :-: | :-- |" if company else "| :-- | :-- | :-- | :-- | :-- | :-: | :-- |"
    lines = [
        f"[p]: {root}assets/practice.svg",
        f"[f]: {root}assets/free.svg",
        "",
        head,
        rule,
    ]
    for q in questions:
        cells = []
        if company is None:
            cells.append(company_cell(q, root))
        title = f"[{esc(q.title)}]({q.url})"
        if company is not None:
            also = company_cell(q, root, skip=company)
            if also != "—":
                title += f"<br><sub>also {also}</sub>"
        cells += [title, round_cell(q), level_cell(q), format_cell(q), practice_cell(q), seen_text(q, today)]
        lines.append("| " + " | ".join(cells) + " |")
    return lines


# ── Shared blocks ────────────────────────────────────────────────────────────


def counts_line(questions: list[Question], today: date) -> str:
    total = len(questions)
    oa = sum(1 for q in questions if "oa" in q.rounds)
    recent = sum(1 for q in questions if is_recent(q, today))
    free = sum(1 for q in questions if q.free)
    parts = [f"**{num(total)} questions**", f"{num(oa)} from an OA", f"{num(recent)} reported in the last {RECENT_DAYS} days", f"{num(free)} free to solve"]
    return " · ".join(parts)


def level_line(questions: list[Question]) -> str:
    """How a page's rows spread over the levels — counts only, every rung."""
    parts = [f"{t.emoji} {t.label} ({num(n)})" for t in LEVEL_TRACKS if (n := sum(1 for q in questions if t.test(q)))]
    return "**By level:** " + " · ".join(parts) if parts else ""


def role_line(questions: list[Question]) -> str:
    parts = [f"{t.emoji} {t.label} ({num(n)})" for t in ROLES if (n := sum(1 for q in questions if t.test(q)))]
    return "**By role:** " + " · ".join(parts) if parts else ""


def rounds_line(questions: list[Question], root: str) -> str:
    counts = Counter(r for q in questions for r in q.rounds)
    parts = [f"{ROUND_EMOJI[r]} {ROUND_SHORT[r]} ({num(counts[r])})" for r in ROUNDS if counts[r]]
    return "**Rounds:** " + " · ".join(parts) if parts else ""


def top_companies(
    questions: list[Question], labels_by_key: dict[str, str], limit: int, only: set[str] | None = None
) -> list[tuple[str, str, int]]:
    counts: Counter[str] = Counter(k for q in questions for k in dict.fromkeys(q.company_keys) if only is None or k in only)
    ordered = sorted(counts.items(), key=lambda kv: (-kv[1], labels_by_key.get(kv[0], kv[0]).lower()))
    return [(key, labels_by_key.get(key, key), n) for key, n in ordered[:limit]]


def company_links(items: list[tuple[str, str, int]], root: str) -> str:
    return " · ".join(f"[{esc(name)} ({num(n)})]({root}companies/{key}.md)" for key, name, n in items)


def paginate(path_stem: str, header: list[str], questions: list[Question], today: date, root: str, company: str | None = None) -> dict[str, str]:
    """``<stem>.md``, ``<stem>-2.md``, … each capped at PAGE_ROWS rows."""
    pages = [questions[i : i + PAGE_ROWS] for i in range(0, len(questions), PAGE_ROWS)] or [[]]
    name = path_stem.rsplit("/", 1)[-1]
    files = {}
    for index, rows in enumerate(pages, start=1):
        path = f"{path_stem}.md" if index == 1 else f"{path_stem}-{index}.md"
        nav = []
        if len(pages) > 1:
            links = []
            for n in range(1, len(pages) + 1):
                target = f"{name}.md" if n == 1 else f"{name}-{n}.md"
                links.append(f"**{n}**" if n == index else f"[{n}]({target})")
            nav = [f"<sub>Page {' · '.join(links)}</sub>", ""]
        body = [*header, *nav]
        if rows:
            body += [f"<sub>{LEGEND}</sub>", "", *table(rows, today, root, company), ""]
        else:
            body += ["_Nothing here yet._", ""]
        body += nav
        files[path] = "\n".join(line for line in body).rstrip() + "\n"
    return files


def labels_by_key(catalog: Catalog) -> dict[str, str]:
    out: dict[str, str] = {}
    for q in catalog.questions:
        for key, name in zip(q.company_keys, q.companies):
            out.setdefault(key, name)
    return out


def company_industries(catalog: Catalog) -> dict[str, frozenset[str]]:
    """Each company's industries, from the company itself — never from the
    other employers a shared question happens to name."""
    out: dict[str, frozenset[str]] = {}
    for q in catalog.questions:
        for name, key in zip(q.companies, q.company_keys):
            if key not in out:
                out[key] = industries_of(name, catalog.labels)
    return out


def company_sectors(catalog: Catalog) -> dict[str, str | None]:
    out: dict[str, str | None] = {}
    for q in catalog.questions:
        for name, key in zip(q.companies, q.company_keys):
            if key not in out:
                out[key] = sector_industry(name, catalog.labels)
    return out


def _header(title: str, nav: str, *blocks: str) -> list[str]:
    lines = [GENERATED, "", f"# {title}", "", nav, ""]
    for block in blocks:
        if block:
            lines += [block, ""]
    return lines


# ── Lists ────────────────────────────────────────────────────────────────────


def list_title(role: str | None, level: str | None) -> str:
    if role and level:
        return f"{LEVEL_TITLES[level]} {ROLE_TITLES[role]} OA & Interview Questions (2026)"
    if role:
        return f"{ROLE_TITLES[role]} OA & Interview Questions (2026)"
    return f"{LEVEL_TITLES[level]} OA & Interview Questions (2026)"


def industry_title(industry: str) -> str:
    entry = INDUSTRY_BY_ID[industry]
    return f"{entry.label} OA & Interview Questions (2026)"


def cut(catalog: Catalog, role: str | None = None, level: str | None = None, industry: str | None = None) -> list[Question]:
    tests = [TRACK_BY_ID[t].test for t in (role, level) if t]
    return [q for q in catalog.questions if all(test(q) for test in tests) and in_industry(q, industry)]


LIST_NAV = "[← Home](../README.md) · [Every list](README.md) · [Every company](../companies/README.md) · [Submit an OA](" + SUBMIT + ")"


def build_lists(catalog: Catalog, today: date) -> dict[str, str]:
    names = labels_by_key(catalog)
    files: dict[str, str] = {}
    index_rows: list[tuple[str, str, str, int]] = []  # (section, slug, title, n)

    cells: list[tuple[str | None, str | None]] = [(None, lvl.id) for lvl in LEVEL_TRACKS]
    cells += [(role.id, None) for role in (*ROLES, *SPECIALTIES)]
    cells += [(role.id, lvl.id) for role in ROLES for lvl in LEVEL_TRACKS]
    for role, level in cells:
        rows = newest_first(cut(catalog, role, level), today)
        if len(rows) < MIN_LIST_ROWS:
            continue
        slug = list_slug(role, level)
        title = list_title(role, level)
        rules = [f"> **Role:** {TRACK_BY_ID[role].rule}"] if role else []
        if level:
            rules.append(f"> **Level:** {TRACK_BY_ID[level].rule}")
        header = [
            *_header(title, LIST_NAV),
            *[line for rule in rules for line in (rule, ">")][:-1],
            "",
            counts_line(rows, today),
            "",
        ]
        for block in (level_line(rows) if not level else "", role_line(rows) if not role else "", rounds_line(rows, "../"),
                      "**Companies:** " + company_links(top_companies(rows, names, 15), "../")):
            if block:
                header += [block, ""]
        files.update(paginate(f"lists/{slug}", header, rows, today, "../"))
        section = "By role and level" if role and level else ("By level" if level else "By role")
        index_rows.append((section, slug, title, len(rows)))

    company_inds = company_industries(catalog)
    for industry in INDUSTRIES:
        rows = newest_first(cut(catalog, industry=industry.id), today)
        if len(rows) < MIN_LIST_ROWS:
            continue
        title = industry_title(industry.id)
        members = {k for k, inds in company_inds.items() if industry.id in inds}
        header = [
            *_header(title, LIST_NAV),
            f"> **Industry:** {industry.rule}",
            "",
            counts_line(rows, today),
            "",
            level_line(rows),
            "",
            role_line(rows),
            "",
            rounds_line(rows, "../"),
            "",
            "**Companies:** " + company_links(top_companies(rows, names, 20, members), "../"),
            "",
        ]
        files.update(paginate(f"lists/{industry.id}", header, rows, today, "../"))
        index_rows.append(("By industry", industry.id, title, len(rows)))

    free = newest_first([q for q in catalog.questions if q.free], today)
    header = [
        *_header("Free OA & Interview Questions — Solve Without a Paid Plan", "[← Home](../README.md) · [Every list](README.md) · [Every company](../companies/README.md)"),
        "> Every question the catalog opens without a paid plan: the full statement, a runnable editor and, on coding, OOD and SQL, a judged verdict. The site decides what is free; this page follows it on every sync.",
        "",
        counts_line(free, today),
        "",
        level_line(free),
        "",
        "**Companies:** " + company_links(top_companies(free, names, 15), "../"),
        "",
    ]
    files.update(paginate("lists/free", header, free, today, "../"))

    lines = [GENERATED, "", "# Every list, and exactly what it selects", "", "[← Home](../README.md)", ""]
    lines += ["Every list is a cut of one bank by **role**, **level** or **industry**. "
              f"A cut with fewer than {MIN_LIST_ROWS} questions gets no page.", ""]
    lines += ["## Role", ""]
    lines += [f"- {t.emoji} **{t.label}** — {t.rule}" for t in (*ROLES, *SPECIALTIES)]
    lines += ["", "## Level", ""]
    lines += [f"- {t.emoji} **{t.label}** — {t.rule}" for t in LEVEL_TRACKS]
    lines += ["", "A question carries the levels and roles **the catalog recorded for it** — reported by the candidate, or inferred from their write-up. "
              "A question reported at two levels is on both lists; a question with no level on record is on no level list: unclassified is not \"every level\".", ""]
    lines += ["## Industry", ""]
    lines += [f"- {i.emoji} **{i.label}** — {i.rule}" for i in INDUSTRIES]
    lines += ["", "An employer the registry has not classified is on no industry list, never guessed into one.", ""]
    for section in ("By level", "By role", "By role and level", "By industry"):
        rows = [r for r in index_rows if r[0] == section]
        if not rows:
            continue
        lines += [f"## {section}", "", "| List | Questions |", "| :-- | --: |"]
        lines += [f"| [{esc(title)}]({slug}.md) | {num(n)} |" for _, slug, title, n in rows]
        lines.append("")
    lines += ["## Everything else", "", "| List | Questions |", "| :-- | --: |",
              f"| [Free to solve](free.md) | {num(len(free))} |",
              f"| [Every question, newest first](../question-bank/README.md) | {num(len(catalog.questions))} |"]
    files["lists/README.md"] = "\n".join(lines) + "\n"
    return files


# ── Rounds, formats, the full bank ───────────────────────────────────────────

BANK_NAV = "[← Home](../README.md) · [Every company](../companies/README.md) · [Every list](../lists/README.md)"


def build_rounds_formats_bank(catalog: Catalog, today: date) -> dict[str, str]:
    names = labels_by_key(catalog)
    files: dict[str, str] = {}
    for r in ROUNDS:
        rows = newest_first([q for q in catalog.questions if r in q.rounds], today)
        if not rows:
            continue
        title = "OA (Online Assessment) Questions (2026)" if r == "oa" else f"{ROUND_LABELS[r]} Interview Questions (2026)"
        header = _header(title, BANK_NAV, counts_line(rows, today), level_line(rows), role_line(rows),
                         "**Companies:** " + company_links(top_companies(rows, names, 20), "../"))
        files.update(paginate(f"rounds/{r}", header, rows, today, "../"))
    for fmt in FORMATS:
        rows = newest_first([q for q in catalog.questions if q.format == fmt], today)
        if not rows:
            continue
        header = _header(f"{FORMAT_TITLES[fmt]} Interview Questions (2026)", BANK_NAV, counts_line(rows, today), level_line(rows),
                         rounds_line(rows, "../"), "**Companies:** " + company_links(top_companies(rows, names, 15), "../"))
        files.update(paginate(f"formats/{fmt}", header, rows, today, "../"))
    rows = newest_first(catalog.questions, today)
    header = _header("Every OA & Interview Question, Newest First", BANK_NAV, counts_line(rows, today), level_line(rows), rounds_line(rows, "../"))
    files.update(paginate("question-bank/README", header, rows, today, "../"))
    # paginate names page 2 after the stem; the bank's stem is README, so its
    # later pages are README-2.md … which reads oddly in a URL. Rename them.
    renamed = {}
    for path, text in files.items():
        if path.startswith("question-bank/README-"):
            n = path[len("question-bank/README-") : -3]
            renamed[f"question-bank/page-{n}.md"] = text
        else:
            renamed[path] = text
    out = {}
    for path, text in renamed.items():
        if path.startswith("question-bank/"):
            for n in range(2, 200):
                text = text.replace(f"(README-{n}.md)", f"(page-{n}.md)")
        out[path] = text
    return out


# ── Companies ────────────────────────────────────────────────────────────────


def _last_reported(rows: list[Question], today: date) -> str:
    dated = [q.seen for q in rows if q.seen and not is_future(q, today)]
    if not dated:
        return "—"
    last = max(dated)
    return f"{MONTHS[last.month - 1]} {last.year}"


def _industry_chip(industry: str | None) -> str:
    entry = INDUSTRY_BY_ID.get(industry or "")
    return f"{entry.emoji} {entry.label}" if entry else "—"


def build_companies(catalog: Catalog, today: date) -> dict[str, str]:
    names = labels_by_key(catalog)
    by_company: dict[str, list[Question]] = {}
    for q in catalog.questions:
        for key in dict.fromkeys(q.company_keys):
            by_company.setdefault(key, []).append(q)
    guides: dict[str, dict[str, str]] = {}
    for g in catalog.guides:
        guides.setdefault(g.company_key, {}).setdefault(g.role, g.url)

    sectors = company_sectors(catalog)
    files: dict[str, str] = {}
    index = []
    for key, qs in by_company.items():
        rows = newest_first(qs, today)
        name = names.get(key, key)
        sector = sectors.get(key)
        oa = sum(1 for q in rows if "oa" in q.rounds)
        chips = [_industry_chip(sector)] if sector else []
        chips.append(f"**{num(len(rows))} questions**")
        if oa:
            chips.append(f"{num(oa)} from an OA")
        last = _last_reported(rows, today)
        if last != "—":
            chips.append(f"last reported {last}")
        guide_links = []
        own = guides.get(key, {})
        if "overview" in own:
            guide_links.append(f"[Overview]({own['overview']})")
        guide_links += [f"[{label}]({own[role]})" for role, label in GUIDE_ROLES.items() if role in own]
        site = catalog.site_company_urls.get(key, f"{SITE}/problems/company/{key}")
        header = _header(
            f"{name} OA & Interview Questions (2026)",
            f"[← Home](../README.md) · [Every company](README.md) · [Practice {esc(name)} on TrueInterview]({site}) · [How {esc(name)} interviews]({SISTER}/blob/main/companies/{key}/README.md)",
            " · ".join(chips),
            level_line(rows),
            role_line(rows),
            rounds_line(rows, "../"),
            ("**📖 Loop guides:** " + " · ".join(guide_links)) if guide_links else "",
        )
        files.update(paginate(f"companies/{key}", header, rows, today, "../", company=key))
        index.append((key, name, sector, rows, oa, last))

    index.sort(key=lambda item: (-len(item[3]), item[1].lower()))
    lines = [GENERATED, "", "# Every Company — OA & Interview Questions", "", "[← Home](../README.md) · [Every list](../lists/README.md)", "",
             "Counts are per company: a question reported at three employers is on three pages.", "",
             "| Company | Industry | Questions | OA | Intern & NG | Mid | Senior | Staff+ | Last reported |",
             "| :-- | :-- | --: | --: | --: | --: | --: | --: | :-- |"]
    for key, name, sector, rows, oa, last in index:
        levels = [_count(sum(1 for q in rows if t.test(q))) for t in LEVEL_TRACKS]
        lines.append(f"| [{esc(name)}]({key}.md) | {_industry_chip(sector)} | {num(len(rows))} | {_count(oa)} | " + " | ".join(levels) + f" | {last} |")
    files["companies/README.md"] = "\n".join(lines) + "\n"
    return files


# ── Data exports ─────────────────────────────────────────────────────────────

EXPORT_FIELDS = ("slug", "title", "url", "companies", "format", "difficulty", "rounds", "seniority", "roles", "role_titles",
                 "reported", "last_reported", "access_tier", "topics")


def export_record(q: Question) -> dict:
    return {
        "slug": q.slug,
        "title": q.title,
        "url": q.url,
        "companies": list(q.companies),
        "format": q.format,
        "difficulty": q.difficulty,
        "rounds": list(q.rounds),
        "seniority": list(q.levels),
        "roles": list(q.roles),
        "role_titles": list(q.role_titles),
        "reported": q.reported,
        "last_reported": q.last_reported,
        "access_tier": q.access_tier,
        "topics": list(q.topics),
    }


def build_data(catalog: Catalog) -> dict[str, str]:
    records = [export_record(q) for q in catalog.questions]
    jsonl = "".join(json.dumps(r, ensure_ascii=False, sort_keys=True) + "\n" for r in records)
    buffer = io.StringIO()
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(EXPORT_FIELDS)
    for r in records:
        writer.writerow(["; ".join(v) if isinstance(v, list) else ("" if v is None else v) for v in (r[f] for f in EXPORT_FIELDS)])
    return {"data/questions.jsonl": jsonl, "data/questions.csv": buffer.getvalue()}


# ── README ───────────────────────────────────────────────────────────────────


def matrix(catalog: Catalog) -> list[str]:
    """Role rows × level columns. Every number opens its list, newest first."""
    head = "| Role ↓ · Level → | " + " | ".join(f"{t.emoji} **{t.label}**<br><sub>{t.hint}</sub>" for t in LEVEL_TRACKS) + " | 🌐 **All levels** |"
    lines = [head, "| :-- | " + " | ".join(":-:" for _ in range(len(LEVEL_TRACKS) + 1)) + " |"]
    for role in (*ROLES, None):
        label = f"{role.emoji} **{role.label}**<br><sub>{role.hint}</sub>" if role else "🗂️ **Every role**<br><sub>incl. unclassified</sub>"
        cells = [label]
        for level in (*LEVEL_TRACKS, None):
            rid, lid = (role.id if role else None), (level.id if level else None)
            n = len(cut(catalog, rid, lid))
            if rid is None and lid is None:
                cells.append(f"[**{num(n)}**](question-bank/README.md)")
            elif n >= MIN_LIST_ROWS:
                cells.append(f"[**{num(n)}**](lists/{list_slug(rid, lid)}.md)")
            else:
                cells.append("—")
        lines.append("| " + " | ".join(cells) + " |")
    return lines


def industry_bar(catalog: Catalog) -> str:
    counted = [(i, len(cut(catalog, industry=i.id))) for i in INDUSTRIES]
    shown = [(i, n) for i, n in counted if n >= MIN_LIST_ROWS]
    # MAANG+ first, then by size: the order a candidate scans for their target.
    shown.sort(key=lambda item: (item[0].id != "maang", -item[1], item[0].label))
    return " · ".join(f"{i.emoji} [{esc(i.label)} ({num(n)})](lists/{i.id}.md)" for i, n in shown)


def specialty_bar(catalog: Catalog) -> str:
    parts = []
    for t in SPECIALTIES:
        n = len(cut(catalog, t.id))
        if n >= MIN_LIST_ROWS:
            parts.append(f"{t.emoji} [{t.label} ({num(n)})](lists/{t.id}.md)")
    return " · ".join(parts)


def oa_leaders(catalog: Catalog, names: dict[str, str], sectors: dict[str, str | None], today: date) -> list[str]:
    """The employers with the most OA questions on record — the question this
    repository is named after — with what their OA is made of."""
    by_company: dict[str, list[Question]] = {}
    for q in catalog.questions:
        if "oa" in q.rounds:
            for key in dict.fromkeys(q.company_keys):
                by_company.setdefault(key, []).append(q)
    ordered = sorted(by_company.items(), key=lambda kv: (-len(kv[1]), names.get(kv[0], kv[0]).lower()))[:TOP_OA_COMPANIES]
    if not ordered:
        return []
    lines = ["| Company | Industry | OA questions | Mostly | Levels | Newest OA |", "| :-- | :-- | --: | :-- | :-- | :-- |"]
    for key, rows in ordered:
        formats = Counter(q.format for q in rows).most_common(2)
        mostly = " · ".join(FORMAT_SHORT.get(f, f) for f, _ in formats)
        levels = " · ".join(t.label for t in LEVEL_TRACKS if any(t.test(q) for q in rows)) or "—"
        newest = newest_first(rows, today)[0]
        lines.append(f"| **[{esc(names.get(key, key))}](companies/{key}.md)** | {_industry_chip(sectors.get(key))} | {num(len(rows))} | {mostly} | {levels} | {seen_text(newest, today)} |")
    return lines


def guides_table(catalog: Catalog, names: dict[str, str], counts: Counter, limit: int = 30) -> list[str]:
    roles = [r for r in ("Software Engineer", "Machine Learning Engineer", "Research Scientist", "AI Engineer", "Data Scientist",
                         "Infrastructure Engineer", "Frontend Engineer", "Quantitative Finance")
             if any(g.role == r for g in catalog.guides)]
    by_company: dict[str, dict[str, str]] = {}
    for g in catalog.guides:
        by_company.setdefault(g.company_key, {}).setdefault(g.role, g.url)
    keys = sorted((k for k in by_company if k in counts), key=lambda k: (-counts[k], names.get(k, k).lower()))
    rows = []
    for key in keys:
        own = by_company[key]
        if "overview" not in own and not any(r in own for r in roles):
            continue
        cells = [f"[{esc(names.get(key, key))}](companies/{key}.md)"]
        cells.append(f"[📖]({own['overview']})" if "overview" in own else "—")
        cells += [f"[📖]({own[r]})" if r in own else "—" for r in roles]
        rows.append("| " + " | ".join(cells) + " |")
        if len(rows) == limit:
            break
    if not rows:
        return []
    head = "| Company | Overview | " + " | ".join(GUIDE_ROLES[r] for r in roles) + " |"
    return [head, "| :-- | " + " | ".join(":-:" for _ in range(len(roles) + 1)) + " |", *rows]


def pick_reports(catalog: Catalog, limit: int = 10, per_company: int = 2) -> list:
    """The newest interview reports at every level, never more than two from one
    company, so a day on which forty reports land from one employer does not
    fill the block."""
    picked, seen = [], Counter()
    for r in catalog.reports:
        if seen[r.company_key] >= per_company:
            continue
        seen[r.company_key] += 1
        picked.append(r)
        if len(picked) == limit:
            break
    return picked


def companies_by_industry(counts: Counter, names: dict[str, str], industries: dict[str, frozenset[str]],
                          sectors: dict[str, str | None], open_lines: int = 5) -> list[str]:
    """MAANG+ first, then every registry sector by size; each company once."""
    def link(k: str) -> str:
        return f"[{esc(names.get(k, k))} ({num(counts[k])})](companies/{k}.md)"

    def order(keys) -> list[str]:
        return sorted(keys, key=lambda k: (-counts[k], names.get(k, k).lower()))

    maang = order(k for k in counts if "maang" in industries.get(k, frozenset()))
    blocks: list[tuple[str, list[str]]] = []
    if maang:
        blocks.append((f"{INDUSTRY_BY_ID['maang'].emoji} {INDUSTRY_BY_ID['maang'].label}", maang))
    rest: dict[str, list[str]] = {}
    for k in counts:
        if k in maang:
            continue
        rest.setdefault(sectors.get(k) or "", []).append(k)
    sector_blocks = []
    for sector, keys in rest.items():
        if not sector:
            continue
        entry = INDUSTRY_BY_ID[sector]
        sector_blocks.append((sum(counts[k] for k in keys), f"{entry.emoji} {entry.label}", order(keys)))
    sector_blocks.sort(key=lambda b: (-b[0], b[1]))
    blocks += [(label, keys) for _, label, keys in sector_blocks]
    if rest.get(""):
        blocks.append(("🌐 Not yet classified", order(rest[""])))

    lines: list[str] = []
    for label, keys in blocks[:open_lines]:
        lines += [f"**{label}:** " + " · ".join(link(k) for k in keys), ""]
    later = blocks[open_lines:]
    if later:
        n = sum(len(keys) for _, keys in later)
        lines += ["<details>", f"<summary><b>🌐 + {n} more companies in {len(later)} more industries</b></summary>", ""]
        for label, keys in later:
            lines += [f"**{label}:** " + " · ".join(link(k) for k in keys), ""]
        lines += ["</details>", ""]
    return lines


