def build(catalog: Catalog, today: date) -> dict[str, str]:
    files: dict[str, str] = {"README.md": build_readme(catalog, today)}
    files.update(build_lists(catalog, today))
    files.update(build_rounds_formats_bank(catalog, today))
    files.update(build_companies(catalog, today))
    files.update(build_data(catalog))
    return files


def over_budget(files: dict[str, str]) -> list[str]:
    problems = []
    for path, text in files.items():
        if not path.endswith(".md"):
            continue
        size = len(text.encode("utf-8"))
        limit = README_MAX_BYTES if path == "README.md" else PAGE_MAX_BYTES
        if size > limit:
            problems.append(f"{path}: {size:,} bytes > {limit:,}")
    return problems
